// Narrow MPI/vendor operations and independent capture/serialization. No authored GPU body.
#include <mpi.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <dlfcn.h>
#include <chrono>
#include <array>
#include <map>
#include <cstring>
#include <iostream>
#include "study_capture.h"
static int rank_,size_,trial_;static std::string model_,capture_;static std::filesystem::path root_,ledgerpath_;static std::ofstream ledger_;static StudyCAS*cas_;
static char csha_[3][3][65]{};static uint64_t counts_[3]{},preps_[3]{};static double preptime_=0;static cudaEvent_t event0_,event1_;
[[noreturn]] static void bad(const char*s){fprintf(stderr,"SPARKLER rank%d %s\n",rank_,s);fflush(stderr);int init=0;MPI_Initialized(&init);if(init)MPI_Abort(MPI_COMM_WORLD,17);std::abort();}
template<class F>static auto safe(F f)->decltype(f()){try{return f();}catch(const std::exception&e){bad(e.what());}}
static void mpi(int e){study_need(e==MPI_SUCCESS,"MPI status");}static void gpu(cudaError_t e){study_need(e==cudaSuccess,cudaGetErrorString(e));}static void blas(cublasStatus_t e){study_need(e==CUBLAS_STATUS_SUCCESS,"cuBLAS status");}
static void*blib_;static decltype(&cublasCreate)create_;static decltype(&cublasDestroy)destroy_;static decltype(&cublasSetStream)setstream_;static decltype(&cublasGetStream)getstream_;static decltype(&cublasGetVersion)version_;static decltype(&cublasSgemm)gemm_;
extern "C" int study_start(const char*model,const char*root){return safe([&](){mpi(MPI_Init(nullptr,nullptr));mpi(MPI_Comm_rank(MPI_COMM_WORLD,&rank_));mpi(MPI_Comm_size(MPI_COMM_WORLD,&size_));study_need(size_==4,"source requires four-rank study");const char*visible=getenv("CUDA_VISIBLE_DEVICES");study_need(visible&&std::string(visible)=="6","GPU6-only visibility required");model_=model;root_=root;std::filesystem::create_directories(root_);uint64_t nonce=rank_==0?std::chrono::system_clock::now().time_since_epoch().count():0;mpi(MPI_Bcast(&nonce,1,MPI_UINT64_T,0,MPI_COMM_WORLD));capture_=std::to_string(nonce);cas_=new StudyCAS(root_/"CAS");blib_=dlopen("/usr/lib/x86_64-linux-gnu/libcublas.so.12",RTLD_NOW|RTLD_LOCAL);study_need(blib_,"pinned cuBLAS dlopen");
#define LOAD(var,sym) var=reinterpret_cast<decltype(var)>(dlsym(blib_,sym));study_need(var,sym)
LOAD(create_,"cublasCreate_v2");LOAD(destroy_,"cublasDestroy_v2");LOAD(setstream_,"cublasSetStream_v2");LOAD(getstream_,"cublasGetStream_v2");LOAD(version_,"cublasGetVersion_v2");LOAD(gemm_,"cublasSgemm_v2");
#undef LOAD
char ver[MPI_MAX_LIBRARY_VERSION_STRING];int len;mpi(MPI_Get_library_version(ver,&len));printf("SPARKLER_MPI rank=%d pid=%d %.*s\n",rank_,getpid(),len,ver);fflush(stdout);return rank_;});}
extern "C" void study_barrier(){safe([](){mpi(MPI_Barrier(MPI_COMM_WORLD));});}
extern "C" uint64_t study_sum_u64(uint64_t x){return safe([&](){uint64_t y;mpi(MPI_Allreduce(&x,&y,1,MPI_UINT64_T,MPI_SUM,MPI_COMM_WORLD));return y;});}
extern "C" double study_sum_f64(double x){return safe([&](){double y;mpi(MPI_Allreduce(&x,&y,1,MPI_DOUBLE,MPI_SUM,MPI_COMM_WORLD));return y;});}
extern "C" void*study_blas_start(void*stream){return safe([&](){cublasHandle_t h;fprintf(stderr,"SPARKLER_VENDOR_CREATE rank%d begin\n",rank_);fflush(stderr);blas(create_(&h));fprintf(stderr,"SPARKLER_VENDOR_CREATE rank%d success\n",rank_);fflush(stderr);blas(setstream_(h,reinterpret_cast<cudaStream_t>(stream)));cudaStream_t actual;blas(getstream_(h,&actual));study_need((void*)actual==stream,"vendor stream handoff mismatch");int version;blas(version_(h,&version));Dl_info info{};study_need(dladdr(reinterpret_cast<void*>(gemm_),&info),"vendor DSO path");int dev;gpu(cudaGetDevice(&dev));study_need(dev==0,"all source ranks must use logical0");printf("SPARKLER_VENDOR rank=%d pid=%d version=%d dso=%s stream=%p device=%d\n",rank_,getpid(),version,info.dli_fname,stream,dev);gpu(cudaEventCreate(&event0_));gpu(cudaEventCreate(&event1_));fflush(stdout);return (void*)h;});}
extern "C" void study_blas_linked_symbol(void*p){safe([&](){study_need(p==reinterpret_cast<void*>(gemm_),"native linked cuBLAS differs from pinned target DSO");});}
extern "C" void study_blas_step(void*h,int m,int n,int k,const float*a,int lda,const float*b,int ldb,float*c,int ldc){safe([&](){const float one=1,zero=0;blas(gemm_(reinterpret_cast<cublasHandle_t>(h),CUBLAS_OP_N,CUBLAS_OP_T,m,n,k,&one,a,lda,b,ldb,&zero,c,ldc));});}
extern "C" void study_blas_finish(void*h){safe([&](){gpu(cudaDeviceSynchronize());gpu(cudaEventDestroy(event0_));gpu(cudaEventDestroy(event1_));blas(destroy_(reinterpret_cast<cublasHandle_t>(h)));});}
extern "C" void study_prep_begin(void*s){safe([&](){gpu(cudaEventRecord(event0_,reinterpret_cast<cudaStream_t>(s)));});}
extern "C" double study_prep_end(void*s,int ci){return safe([&](){gpu(cudaEventRecord(event1_,reinterpret_cast<cudaStream_t>(s)));gpu(cudaEventSynchronize(event1_));float ms;gpu(cudaEventElapsedTime(&ms,event0_,event1_));double dt=ms*.001;preptime_+=dt;preps_[ci]++;return dt;});}
extern "C" void study_begin_trial(int t){safe([&](){trial_=t;memset(csha_,0,sizeof(csha_));memset(counts_,0,sizeof(counts_));memset(preps_,0,sizeof(preps_));preptime_=0;if(ledger_.is_open())ledger_.close();auto dir=root_/model_;std::filesystem::create_directories(dir);ledgerpath_=dir/(capture_+"_rank"+std::to_string(rank_)+"_trial"+std::to_string(t)+".jsonl");ledger_.open(ledgerpath_);study_need(ledger_.good(),"capture ledger open");printf("SPARKLER_LEDGER rank=%d trial=%d path=%s\n",rank_,t,ledgerpath_.c_str());fflush(stdout);});}
static void guards(const unsigned char*p,size_t n){study_need(n>=512,"physical length");for(size_t i=0;i<256;i++)study_need(p[i]==0xa5&&p[n-256+i]==0xa5,"actual matrix guard bytes");}
static std::map<std::array<uint64_t,5>,std::vector<float>> expected_;
extern "C" void study_input_frame(const unsigned char*p,size_t bytes,int ci,int iteration,int step,int role,uint64_t rows,uint64_t cols,uint64_t ld,uint64_t ac,uint64_t base){safe([&](){std::vector<unsigned char>v(p,p+bytes);std::string sha=cas_->put(v);ledger_<<"{\"kind\":\"input\",\"case\":"<<ci<<",\"iteration\":"<<iteration<<",\"step\":"<<step<<",\"role\":"<<role<<",\"rows\":"<<rows<<",\"cols\":"<<cols<<",\"ld\":"<<ld<<",\"allocated_cols\":"<<ac<<",\"base\":"<<base<<",\"bytes\":"<<bytes<<",\"sha256\":"<<study_quote(sha)<<"}\n";ledger_.flush();guards(p,bytes);study_need(bytes==ld*ac*4+512,"input physical shape");std::array<uint64_t,5>key{rows,cols,ld,ac,base};auto it=expected_.find(key);if(it==expected_.end())it=expected_.emplace(key,study_expected_input(rows,cols,ld,ac,base)).first;study_need(memcmp(p+256,it->second.data(),it->second.size()*4)==0,"full actual binary input/padding oracle");});}
extern "C" void study_output_frame(const unsigned char*p,size_t bytes,int ci,int iteration,int step,uint64_t m,uint64_t ld,uint64_t ac,uint64_t left,uint64_t right,uint64_t fields){safe([&](){std::vector<unsigned char>v(p,p+bytes);std::string sha=cas_->put(v);ledger_<<"{\"kind\":\"output\",\"case\":"<<ci<<",\"iteration\":"<<iteration<<",\"step\":"<<step<<",\"m\":"<<m<<",\"ld\":"<<ld<<",\"allocated_cols\":"<<ac<<",\"left_base\":"<<left<<",\"right_base\":"<<right<<",\"fields\":"<<fields<<",\"bytes\":"<<bytes<<",\"sha256\":"<<study_quote(sha)<<"}\n";ledger_.flush();guards(p,bytes);study_need(bytes==ld*ac*4+512,"output physical shape");study_check_C(reinterpret_cast<const float*>(p+256),m,ld,ac,left,right,fields);study_need(ci>=0&&ci<3&&step>=1&&step<=3,"output key");if(csha_[ci][step-1][0])study_need(sha==csha_[ci][step-1],"repeated source matrix outputs changed");else memcpy(csha_[ci][step-1],sha.c_str(),65);counts_[ci]++;});}
extern "C" void study_guard_frame(const unsigned char*p,int ci,int iteration,int step,int role){safe([&](){std::vector<unsigned char>v(p,p+512);auto sha=cas_->put(v);ledger_<<"{\"kind\":\"guards\",\"case\":"<<ci<<",\"iteration\":"<<iteration<<",\"step\":"<<step<<",\"role\":"<<role<<",\"sha256\":"<<study_quote(sha)<<",\"bytes\":512}\n";ledger_.flush();for(auto b:v)study_need(b==0xa5,"actual input post-GEMM guard bytes");});}
static std::vector<unsigned char>ungzip(const std::filesystem::path&p,size_t bytes){gzFile f=gzopen(p.c_str(),"rb");study_need(f,"CAS reopen");std::vector<unsigned char>v(bytes);size_t off=0;while(off<bytes){int n=gzread(f,v.data()+off,std::min<size_t>(1<<20,bytes-off));study_need(n>0,"CAS short decode");off+=n;}unsigned char b;study_need(gzread(f,&b,1)==0,"CAS extra bytes");study_need(gzclose(f)==Z_OK,"CAS read close");return v;}
extern "C" void study_write_trial(int t,double seconds,const uint64_t*hashes,const double*flops){safe([&](){for(int ci=0;ci<3;ci++){auto c=study_cases()[ci];study_need(counts_[ci]==uint64_t((rank_<2?3:2)*c.iterations),"all active output calls captured");study_need(preps_[ci]==1+counts_[ci],"all authored prep calls counted");study_need(hashes[ci]==study_global_hash(c),"independent global UInt64 checksum");uint64_t m=2*((c.vectors+3)/4);study_need(flops[ci]==double(2*m*m*c.fields*10*c.iterations),"full vendor flop count");}ledger_.flush();study_need(ledger_.good(),"ledger flush");char allsha[4][3][3][65];mpi(MPI_Gather(csha_,sizeof(csha_),MPI_BYTE,allsha,sizeof(csha_),MPI_BYTE,0,MPI_COMM_WORLD));double prepall[4];mpi(MPI_Gather(&preptime_,1,MPI_DOUBLE,prepall,1,MPI_DOUBLE,0,MPI_COMM_WORLD));if(rank_!=0)return;std::vector<uint32_t>out{3,4,4000,90000,10,17,31,3,2,1,2};auto push64=[&](uint64_t v){out.push_back(uint32_t(v));out.push_back(uint32_t(v>>32));};
for(int ci=0;ci<3;ci++){auto c=study_cases()[ci];uint64_t m=2*((c.vectors+3)/4),ld=((m+7)/8)*8;out.push_back(ci);out.push_back(c.vectors);out.push_back(c.fields);out.push_back(c.iterations);push64(hashes[ci]);push64(uint64_t(flops[ci]));out.push_back(10);out.push_back(10*c.iterations);out.push_back(4+10*c.iterations);out.push_back(10*ld*ld);for(int rank=0;rank<4;rank++)for(int step=1;step<=(rank<2?3:2);step++){int right=(rank+step-1)%4;uint64_t bl=c.vectors*rank/4,br=c.vectors*right/4;std::string sha=allsha[rank][ci][step-1];study_need(sha.size()==64,"complete active matrix SHA membership");auto v=ungzip(cas_->dir/(sha+".bin.gz"),ld*ld*4+512);study_need(study_sha(v.data(),v.size())==sha,"full CAS bytes rehash");out.insert(out.end(),{uint32_t(rank),uint32_t(step),uint32_t(m),uint32_t(ld),uint32_t(ld),uint32_t(bl),uint32_t(br),uint32_t(c.iterations),uint32_t(ld*ld)});const uint32_t*p=reinterpret_cast<const uint32_t*>(v.data()+256);out.insert(out.end(),p,p+ld*ld);}}
study_need(out.size()==40003517,"complete primary word count");std::string path="trial"+std::to_string(t)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();study_need(f.good(),"primary file write");printf("\nSTUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"jit_excluded\":true,\"timing_region\":\"rank0_sum45_source_GEMM_stream_context_complete_MPI_barrier_intervals\",\"internal_repeats\":1,\"prep_rank_event_seconds\":[%.17g,%.17g,%.17g,%.17g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",t,seconds,out.size(),prepall[0],prepall[1],prepall[2],prepall[3],path.c_str(),out.size());fflush(stdout);});}
extern "C" void study_finish(){safe([](){if(ledger_.is_open())ledger_.close();delete cas_;mpi(MPI_Finalize());});}
